parameters.query:
select public.olivia_context_v2_b64($1) || jsonb_build_object('base_documents',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'title',title,'content',content,'source_url',source_url,'updated_at',updated_at) order by updated_at,id),'[]'::jsonb) as docs
from public.product_documents where approval_status='approved' and routing_packages && array['always']
and not routing_packages && array['internal_ops'])) as context;

parameters.jsCode:
const ctx = $('Desempaquetar contexto').item.json;
const raw = typeof $json.output==='string' ? JSON.parse($json.output) : ($json.output ?? {});
const allowed = new Set(['early_access','products','orders','support','opt_out','reference', ...(ctx.document_index??[]).flatMap(d=>d.packages??[])].filter(x=>typeof x==='string'&&!['internal_ops','always','black_friday'].includes(x)));
const packages = [...new Set((raw.knowledge_packages??[]).filter(x=>allowed.has(x)))].slice(0,3);
const tags = ctx.contact?.tags ?? [];
const registered = tags.includes('bf2026_early_access');
const literalStop = /^(?:stop|baja|unsubscribe|no me escribas m[aá]s|no me escrib[aá]is m[aá]s|no quiero recibir m[aá]s mensajes)[\s.!]*$/i.test(String(ctx.batch_text??'').trim());
const decision = {
 ...raw,
 knowledge_packages:packages,
 product_ids:(raw.product_ids??[]).filter(id=>(ctx.products??[]).some(p=>p.id===id)).slice(0,4),
 opt_out:literalStop||raw.opt_out===true,
 opt_out_scope:literalStop?'whatsapp':(['email','all'].includes(raw.opt_out_scope)?raw.opt_out_scope:'whatsapp'),
 needs_human:raw.needs_human===true,
 early_access_action:registered?'already_registered':(['offer_registration','registration_requested'].includes(raw.early_access_action)?raw.early_access_action:'none'),
 summary:String(raw.summary??ctx.lead_state?.summary??'').slice(0,2400),
 pending_question:String(raw.pending_question??'').slice(0,300),
 prompt_version:'bf26-v2'
};
if(decision.opt_out) { decision.early_access_action='none'; decision.product_ids=[]; decision.knowledge_packages=['opt_out']; decision.pending_question=''; }
if(registered && decision.intent==='early_access') decision.pending_question='';
if(decision.needs_human) decision.pending_question='';
if(decision.intent==='early_access' && !/(?:jengibre|canela|menta|café|cafe|kema|magnesio|mg4|col[aá]geno)/i.test(ctx.batch_text??'')) decision.product_ids=[];

if(!/(?:receta|recetario|gu[ií]a|documento|recurso)/i.test(ctx.batch_text??'')) decision.knowledge_packages=decision.knowledge_packages.filter(x=>x!=='reference');
if(!registered && decision.intent==='early_access' && !decision.opt_out) {
 if(decision.early_access_action==='registration_requested' && !ctx.campaign?.registration_url) {
  decision.needs_human=true;
  decision.pending_question='';
  decision.response_brief='La persona solicita inscribirse, pero no hay enlace ni herramienta de alta en este turno. Indica que el equipo debe ayudar a completar la inscripción; no confirmes un alta realizada.';
 } else if(decision.early_access_action==='offer_registration' && !ctx.campaign?.registration_url) {
  decision.pending_question='¿Quieres que el equipo te ayude a completar la inscripción?';
  decision.response_brief='Explica la ventaja confirmada en la Base permanente y las condiciones vigentes. Ofrece ayuda del equipo para completar la inscripción. No ofrezcas enviar un enlace que no está disponible. No expliques herramientas ni configuraciones internas: ofrece la ayuda del equipo con naturalidad.';
 } else if(decision.early_access_action==='offer_registration' && ctx.campaign?.registration_url) {
  decision.pending_question='';
  decision.response_brief='Explica la ventaja y comparte directamente el enlace real de registro de campaign.registration_url. No pidas permiso para compartir el enlace solicitado.';
 }
}

if(!decision.pending_question) decision.response_brief=String(decision.response_brief??'').replace(/¿[^?]*\?/g,'').trim();
if(decision.needs_human) decision.response_brief='Confirma brevemente que la solicitud pasa a revisión del equipo. No introduzcas promoción ni pidas datos accesorios.';
if(ctx.conversation?.handoff_status==='human') decision.suppress_reply=true;
return {json:{...ctx,decision,payload_b64:Buffer.from(JSON.stringify({...ctx,decision}),'utf8').toString('base64')}};
